using System;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;
using Job=BoundCadEditsV6.Job;
public static class PaperTransformOpsV1 {
 public class Item {public string handle,type,layer;public object before;public double scale_x,offset_x,offset_y;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}
 static Point2d Move(Point2d p,Item i){return new Point2d(p.X*i.scale_x+i.offset_x,p.Y+i.offset_y);}
 static Entity Open(Database db,Transaction tr,string h,OpenMode m){return (Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),m);}
 static object Stable(Entity e){var p=e as Polyline;var h=e as Hatch;return new{handle=e.Handle.ToString(),type=e.GetRXClass().Name,owner=e.OwnerId.Handle.ToString(),layer=e.Layer,color=e.Color.ToString(),linetype=e.Linetype,lineweight=e.LineWeight,ltscale=e.LinetypeScale,visible=e.Visible,transparency=e.Transparency.ToString(),normal=p!=null?new[]{p.Normal.X,p.Normal.Y,p.Normal.Z}:new[]{h.Normal.X,h.Normal.Y,h.Normal.Z},elevation=p!=null?p.Elevation:h.Elevation,poly=p==null?null:new{closed=p.Closed,thickness=p.Thickness,vertices=p.NumberOfVertices,widths=Enumerable.Range(0,p.NumberOfVertices).Select(k=>new[]{p.GetStartWidthAt(k),p.GetEndWidthAt(k)}).ToArray()},hatch=h==null?null:new{h.PatternName,h.PatternType,h.PatternScale,h.PatternAngle,h.PatternDouble,h.HatchStyle,h.Associative,loops=Enumerable.Range(0,h.NumberOfLoops).Select(k=>(int)h.GetLoopAt(k).LoopType).ToArray()}};}
 static List<Point2d> Points(Entity e){var p=e as Polyline;if(p!=null)return Enumerable.Range(0,p.NumberOfVertices).Select(p.GetPoint2dAt).ToList();var h=(Hatch)e;var pts=new List<Point2d>();for(int k=0;k<h.NumberOfLoops;k++){var l=h.GetLoopAt(k);Need(!l.IsPolyline,"PAPER_HATCH_LINE_LOOPS_REQUIRED");foreach(Curve2d edge in l.Curves){var line=edge as LineSegment2d;Need(line!=null,"PAPER_HATCH_ARC_NOT_SUPPORTED");pts.Add(line.StartPoint);pts.Add(line.EndPoint);}}return pts;}
 static void Check(Entity e,Item i,ObjectId owner){Need(e.OwnerId==owner&&e.GetRXClass().Name==i.type&&e.Layer==i.layer,"PAPER_TRANSFORM_IDENTITY");Need(i.scale_x>0&&!Double.IsNaN(i.scale_x)&&!Double.IsInfinity(i.scale_x)&&!Double.IsNaN(i.offset_x)&&!Double.IsInfinity(i.offset_x)&&!Double.IsNaN(i.offset_y)&&!Double.IsInfinity(i.offset_y),"FINITE_POSITIVE_X_TRANSFORM_REQUIRED");Need(CadValueCompareV1.Json(J.Serialize(NativeGeometryReadV1.Geometry(e)),J.Serialize(i.before)),"PAPER_ORIGINAL_GEOMETRY_CHANGED:"+i.handle);var p=e as Polyline;var h=e as Hatch;Need(p!=null||h!=null,"PAPER_POLYLINE_SOLID_ONLY");var normal=p!=null?p.Normal:h.Normal;Need((normal-Vector3d.ZAxis).Length<1e-10,"PAPER_POSITIVE_Z_PLANE_REQUIRED");if(p!=null)for(int k=0;k<p.NumberOfVertices;k++)Need(Math.Abs(p.GetBulgeAt(k))<1e-12,"PAPER_POLYLINE_ARC_NOT_SUPPORTED");if(h!=null)Need(h.PatternName.Equals("SOLID",StringComparison.OrdinalIgnoreCase)&&!h.Associative,"PAPER_NONASSOCIATIVE_SOLID_REQUIRED");Points(e);}
 public static string DrawOrder(Database db,string layout){using(var tr=db.TransactionManager.StartTransaction()){var owner=BoundCadEditsV6.Space(tr,db,layout);var b=(BlockTableRecord)tr.GetObject(owner,OpenMode.ForRead);if(b.DrawOrderTableId.IsNull)return J.Serialize(new{owner=owner.Handle.ToString(),table=(string)null,order=b.Cast<ObjectId>().Select(id=>id.Handle.ToString()).ToArray()});var o=(DrawOrderTable)tr.GetObject(b.DrawOrderTableId,OpenMode.ForRead);return J.Serialize(new{owner=owner.Handle.ToString(),table=o.Handle.ToString(),order=o.GetFullDrawOrder(0).Cast<ObjectId>().Select(id=>id.Handle.ToString()).ToArray()});}}
 public static string Snapshot(Database db,Job job){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction())foreach(var i in job.transforms){var e=Open(db,tr,i.handle,OpenMode.ForRead);rows.Add(new{stable=Stable(e),geometry=NativeGeometryReadV1.Geometry(e)});}return J.Serialize(new{entities=rows,draw_order=J.DeserializeObject(DrawOrder(db,job.layout))});}
 public static object Apply(Database db,Job job,Action mutate,Action committed=null){Need(job.layout!="Model"&&job.transforms!=null&&job.transforms.Length>0&&job.transforms.Select(i=>i.handle.ToUpperInvariant()).Distinct().Count()==job.transforms.Length,"UNIQUE_PAPER_TRANSFORMS_REQUIRED");var selected=new HashSet<string>(job.transforms.Select(i=>i.handle),StringComparer.OrdinalIgnoreCase);var touched=new HashSet<string>();string orderBefore=DrawOrder(db,job.layout),orderHandle=null;int orderNotifications=0;using(var rt=db.TransactionManager.StartTransaction()){var b=(BlockTableRecord)rt.GetObject(BoundCadEditsV6.Space(rt,db,job.layout),OpenMode.ForRead);if(!b.DrawOrderTableId.IsNull)orderHandle=b.DrawOrderTableId.Handle.ToString();}
  ObjectEventHandler changed=(s,a)=>{if(a.DBObject is DrawOrderTable&&a.DBObject.Handle.ToString()==orderHandle){orderNotifications++;return;}if(!selected.Contains(a.DBObject.Handle.ToString()))touched.Add(a.DBObject.Handle.ToString());};ObjectErasedEventHandler erased=(s,a)=>{if(a.Erased)touched.Add("erased:"+a.DBObject.Handle.ToString());};
  using(var tr=db.TransactionManager.StartTransaction()){var owner=BoundCadEditsV6.Space(tr,db,job.layout);foreach(var i in job.transforms)Check(Open(db,tr,i.handle,OpenMode.ForRead),i,owner);
   db.ObjectModified+=changed;db.ObjectAppended+=changed;db.ObjectErased+=erased;try{mutate();foreach(var i in job.transforms){var e=Open(db,tr,i.handle,OpenMode.ForWrite);string stable=J.Serialize(Stable(e));var expected=Points(e).Select(pt=>Move(pt,i)).ToArray();var p=e as Polyline;if(p!=null){for(int k=0;k<p.NumberOfVertices;k++)p.SetPointAt(k,Move(p.GetPoint2dAt(k),i));}else{var h=(Hatch)e;var loops=new List<Tuple<HatchLoopTypes,Point2d[]>>();for(int k=0;k<h.NumberOfLoops;k++){var l=h.GetLoopAt(k);var pts=new List<Point2d>();foreach(LineSegment2d edge in l.Curves){pts.Add(Move(edge.StartPoint,i));pts.Add(Move(edge.EndPoint,i));}loops.Add(Tuple.Create(l.LoopType,pts.ToArray()));}for(int k=h.NumberOfLoops-1;k>=0;k--)h.RemoveLoopAt(k);foreach(var l in loops){var curves=new Curve2dCollection();try{var kinds=new IntegerCollection();for(int k=0;k<l.Item2.Length;k+=2){curves.Add(new LineSegment2d(l.Item2[k],l.Item2[k+1]));kinds.Add(1);}h.AppendLoop(l.Item1,curves,kinds);}finally{foreach(Curve2d edge in curves)edge.Dispose();}}h.EvaluateHatch(true);}e.RecordGraphicsModified(true);var actual=Points(e);Need(actual.Count==expected.Length&&actual.Where((q,k)=>q.GetDistanceTo(expected[k])>1e-8).Count()==0,"PAPER_TRANSFORM_GEOMETRY_MISMATCH");Need(stable==J.Serialize(Stable(e)),"PAPER_DISPLAY_OR_Z_CHANGED");}Need(touched.Count==0,"UNSELECTED_OBJECT_MODIFIED:"+String.Join(",",touched));tr.Commit();if(committed!=null)committed();Need(orderBefore==DrawOrder(db,job.layout),"PAPER_DRAW_ORDER_CHANGED");Need(touched.Count==0,"UNSELECTED_OBJECT_MODIFIED_AT_COMMIT:"+String.Join(",",touched));}finally{db.ObjectModified-=changed;db.ObjectAppended-=changed;db.ObjectErased-=erased;}}
  return new{operation="paper_transform",updated=job.transforms.Select(i=>i.handle).ToArray(),unselected_objects_protected=true,handles_and_display_and_z_preserved=true,draw_order_preserved=true,draw_order_notifications=orderNotifications,geometry=J.DeserializeObject(Snapshot(db,job))};
 }
}


